import React, { useState } from 'react';

function SearchCar() {
    const [filters, setFilters] = useState<{
    brand: string;
    model: string;
    year: string;
    features: string[];
    }>({
        brand: '',
        model: '',
        year: '',
        features: [],
    });


    const handleChange = (e: React.ChangeEvent<HTMLSelectElement | HTMLInputElement>) => {
        const { name, value } = e.target;
        setFilters(prev => ({
            ...prev,
            [name]: value,
        }));
    };

    const handleFeaturesChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { value, checked } = e.target;
        setFilters(prev => ({
            ...prev,
            features: checked
                ? [...prev.features, value]
                : prev.features.filter(f => f !== value),
        }));
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        console.log('Поиск по фильтрам:', filters);
        // Здесь можно вызвать API или отфильтровать локальные данные
    };

    return (
        <div className="max-w-4xl mx-auto bg-white p-8 rounded-lg shadow">
            <div className="text-3xl font-semibold text-center mb-6">Find car!</div>

            <form onSubmit={handleSubmit} className="space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block mb-1">Марка</label>
                        <select
                            name="brand"
                            value={filters.brand}
                            onChange={handleChange}
                            className="w-full border p-2 rounded"
                        >
                            <option value="">-- Избери --</option>
                            <option value="Toyota">Toyota</option>
                            <option value="BMW">BMW</option>
                            <option value="Audi">Audi</option>
                        </select>
                    </div>

                    <div>
                        <label className="block mb-1">Модел</label>
                        <input
                            type="text"
                            name="model"
                            value={filters.model}
                            onChange={handleChange}
                            placeholder="напр. Corolla"
                            className="w-full border p-2 rounded"
                        />
                    </div>

                    <div>
                        <label className="block mb-1">Година</label>
                        <input
                            type="number"
                            name="year"
                            value={filters.year}
                            onChange={handleChange}
                            placeholder="напр. 2020"
                            className="w-full border p-2 rounded"
                        />
                    </div>
                </div>

                <div>
                    <label className="block mb-2">Екстри</label>
                    <div className="flex flex-wrap gap-4">
                        {['Навигация', 'Климатик', 'Кожен салон', 'Парктроник'].map(feature => (
                            <label key={feature} className="flex items-center gap-2">
                                <input
                                    type="checkbox"
                                    value={feature}
                                    checked={filters.features.includes(feature)}
                                    onChange={handleFeaturesChange}
                                />
                                {feature}
                            </label>
                        ))}
                    </div>
                </div>

                <button
                    type="submit"
                    className="mt-4 bg-blue-600 hover:bg-blue-700 text-white py-2 px-6 rounded"
                >
                    Търси
                </button>
            </form>
        </div>
    );
}

export default SearchCar;
